<script>
(()=>{const L=document.getElementById('pgDl');if(!L)return;const ty=L.querySelector('.pgD-ty'),qs=[...document.querySelectorAll('.pgD-q')],rm=matchMedia('(prefers-reduced-motion:reduce)').matches;let busy=false,auto=true,tm;
const bottom=()=>L.scrollTo({top:L.scrollHeight,behavior:rm?'auto':'smooth'});
const ask=(k,byUser)=>{if(busy)return;const qa=L.querySelector('.pgD-qa[data-k="'+k+'"]');const b=qs.find(x=>x.dataset.k==k);if(!qa||!qa.hidden)return;busy=true;if(byUser){auto=false;clearTimeout(tm)}if(b)b.remove();
 const u=qa.querySelector('.u'),a=qa.querySelector('.b');a.hidden=true;qa.hidden=false;L.insertBefore(qa,ty);u.classList.add('pop');bottom();
 setTimeout(()=>{ty.hidden=false;bottom();setTimeout(()=>{ty.hidden=true;a.hidden=false;a.classList.add('pop');busy=false;
  const top=qa.offsetTop-L.offsetTop-8;L.scrollTo({top:Math.max(0,top),behavior:rm?'auto':'smooth'});if(auto)next()},rm?0:900)},rm?0:350)};
const next=()=>{clearTimeout(tm);const q=qs.find(x=>document.contains(x));if(q&&auto)tm=setTimeout(()=>ask(q.dataset.k,false),5200)};
qs.forEach(q=>q.addEventListener('click',()=>ask(q.dataset.k,true)));
L.addEventListener('wheel',()=>{auto=false;clearTimeout(tm)},{passive:true});L.addEventListener('touchstart',()=>{auto=false;clearTimeout(tm)},{passive:true});
const io=new IntersectionObserver(e=>{if(e[0].isIntersecting){io.disconnect();if(!rm)next()}},{threshold:.5});io.observe(L);})();
</script>
